export function optionArt(id,c){
 const sticker=(mark,label,cls='')=>`<div class="answer-illustration ${cls}"><span class="answer-mark">${mark}</span><span class="answer-art-label">${label}</span><i class="art-dot dot-one"></i><i class="art-dot dot-two"></i></div>`;
 if(id==='nickname')return c?sticker('F','HELLO, FRANKLIN','art-name'):`<div class="answer-illustration art-profile"><img src="assets/profile.webp" alt="" class="answer-avatar"><span class="answer-art-label">OUR FAVOURITE PLAYER</span><i class="art-dot dot-one"></i></div>`;
 if(id==='night')return sticker(c?'🍰':'🏐',c?'SWEET TOOTH':'MIDNIGHT PLAYER',c?'art-dessert':'art-volleyball');
 if(id==='mall')return sticker(c?'🧴':'💻',c?'A LITTLE SCENT':'TECH EXPLORER');
 if(id==='dog')return `<div class="answer-illustration art-dog"><svg viewBox="0 0 200 150" aria-hidden="true"><ellipse cx="104" cy="129" rx="57" ry="8" fill="#d9baa0"/><rect x="54" y="84" width="100" height="41" rx="20" fill="${c?'#ce8a48':'#ddb075'}"/><path d="M59 109v20m31-20v20m39-20v20m19-20v20" stroke="${c?'#f5dfb6':'#c58e52'}" stroke-width="12" stroke-linecap="round"/><path d="M149 90q32-17 19-33" fill="none" stroke="#d49e61" stroke-width="13" stroke-linecap="round"/>${c?'<path d="M49 58L45 20 72 46M85 46L109 21 104 65" fill="#ce8a48" stroke="#b87e41" stroke-width="3"/>':'<ellipse cx="40" cy="69" rx="14" ry="32" fill="#bb8446"/><ellipse cx="103" cy="69" rx="14" ry="32" fill="#bb8446"/>'}<rect x="39" y="40" width="66" height="63" rx="27" fill="${c?'#d49553':'#deb278'}"/><ellipse cx="70" cy="84" rx="25" ry="17" fill="#fff0d0"/><circle cx="56" cy="66" r="4" fill="#353547"/><circle cx="86" cy="66" r="4" fill="#353547"/><ellipse cx="70" cy="80" rx="7" ry="5" fill="#353547"/><path d="M68 86q2 9 9 2" fill="none" stroke="#927152" stroke-width="2"/></svg><span class="answer-art-label">${c?'SHORT LEGS, BIG LOVE':'GOLDEN FRIEND'}</span></div>`;
 if(id==='university')return sticker('🎓',c?'PKU':'U OF T','art-campus');
 if(id==='sauce')return `<div class="answer-illustration art-sauce"><span class="sauce-spoon"></span><span class="sauce-bowl"><i></i></span><span class="answer-art-label">${c?'SESAME SAUCE':'PEANUT SAUCE'}</span></div>`;
 if(id==='career')return sticker(c?'⌨️':'🧑‍💼',c?'HELLO, WORLD':'PEOPLE & POSSIBILITIES');
 if(id==='birthday')return sticker(c?'🗓️':'🎂',c?'JANUARY 12':'JANUARY 21');
 if(id==='spice')return sticker(c?'🌶️':'🥛',c?'BRING THE HEAT':'MILD PLEASE');
 return sticker(c?'🍌':'🍎',c?'BANANA BREAK':'APPLE A DAY','art-fruit');
}
export function quizScene(level,answered){return `<div class="quiz-stage" id="quiz-stage"><div class="pool-scene-head"><span>FRIENDSHIP POOL</span><span id="water-level">默契水位 ${level} / 10</span></div><div class="pool-tiles"><div class="pool-lanes"></div><div class="level-rail">${Array.from({length:10},(_,i)=>`<span class="${i<level?'lit':''}"></span>`).join('')}</div><div class="quiz-token" id="quiz-token" style="--rise:${level*7.8}%;--rise-small:${level*4.5}%"><span class="volley-seam seam-one"></span><span class="volley-seam seam-two"></span><span class="token-name">FRIEND</span><span class="token-shine"></span></div><div class="pool-ripple ripple-one"></div><div class="pool-ripple ripple-two"></div><div class="pool-ripple ripple-three"></div><div class="pool-doodle">✧</div></div><div class="pool-deck"><div class="quiz-host"><span class="host-bubble" id="host-bubble">选一个，看看有多默契。</span><span class="host-photo"><img src="assets/profile.webp" alt="Franklin使用的狗狗头像"></span><span class="host-name">FRANKLIN</span></div><div class="mini-luggage"><span class="luggage-handle"></span><i></i><i></i><i></i><span>SG</span></div><div class="quiz-side-bubble" id="side-bubble">${answered} 段回忆已找回</div></div><div class="confetti-box" id="quiz-confetti" aria-hidden="true"></div></div>`;}
